using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace Meziantou.Framework.Yaml.SourceGeneration;

public sealed partial class YamlSerializerContextGenerator
{
    private static string GetThrowHelperContent()
    {
        using var stream = typeof(YamlSerializerContextGenerator).Assembly.GetManifestResourceStream("Meziantou.Framework.Yaml.Serialization.YamlThrowHelper.cs");
        if (stream is null)
        {
            throw new InvalidOperationException("Could not find embedded resource 'Meziantou.Framework.Yaml.Serialization.YamlThrowHelper.cs'");
        }

        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }

    private static bool EmitContext(SourceProductionContext context, Compilation compilation, ContextModel model)
    {
        var validationResult = ValidateContext(compilation, model);
        if (validationResult.HasErrors)
        {
            return false;
        }

        var source = GenerateContextSource(compilation, model, validationResult.DerivedTypeMappings, validationResult.ResolvedTypes, validationResult.IndexByType);
        context.AddSource($"{model.TypeName}.g.cs", SourceText.From(source, Encoding.UTF8));
        return true;
    }

    private static string GenerateContextSource(
        Compilation compilation,
        ContextModel model,
        ImmutableArray<DerivedTypeMappingModel> derivedTypeMappings,
        ImmutableArray<ITypeSymbol> types,
        Dictionary<ITypeSymbol, int> indexByType)
    {
        var builder = new StringBuilder();
        var pendingMembers = new StringBuilder();
        var accessors = new UnsafeAccessorRegistry(compilation, model.ContextSymbol);
        var propertyNamingPolicy = ResolveNamingPolicy(model.SourceGenerationOptions.PropertyNamingPolicy);
        var runtimeCustomConverterTypes = CollectRuntimeCustomConverterTypes(types);
        builder.AppendLine("// <auto-generated/>");
        builder.AppendLine("#pragma warning disable");
        builder.AppendLine("#nullable enable");
        builder.AppendLine();
        builder.AppendLine("using System.Collections.Frozen;");
        builder.AppendLine("using System;");
        builder.AppendLine();

        if (!string.IsNullOrEmpty(model.NamespaceName))
        {
            builder.Append("namespace ").Append(model.NamespaceName).AppendLine(";");
            builder.AppendLine();
        }

        AppendGeneratedTypeAttributes(builder, string.Empty);
        builder.Append("partial class ").Append(model.TypeName).AppendLine();
        builder.AppendLine("{");
        EmitSourceGenerationConverterFields(builder, model.SourceGenerationOptions);
        EmitCSharpUnionClassifierContextFields(builder, types, propertyNamingPolicy, accessors, model.SourceGenerationOptions);
        EmitRuntimeCustomConverterHelpers(builder, model.SourceGenerationOptions, runtimeCustomConverterTypes);
        builder.AppendLine();
        builder.Append("    public static ").Append(model.TypeName).AppendLine(" Default { get; } = new(CreateDefaultOptions(), isDefault: true);");
        builder.AppendLine();
        if (!model.ContextSymbol.InstanceConstructors.Any(static ctor => ctor.Parameters.Length == 0 && !ctor.IsImplicitlyDeclared))
        {
            builder.Append("    public ").Append(model.TypeName).AppendLine("() : base() { }");
            builder.AppendLine();
        }

        builder.Append("    private ").Append(model.TypeName).AppendLine("(global::Meziantou.Framework.Yaml.YamlSerializerOptions options, bool isDefault) : base(options)");
        builder.AppendLine("    {");
        builder.AppendLine("        _runtimeConverters = new RuntimeCustomConverterCache(options);");
        builder.AppendLine("    }");
        builder.AppendLine();
        builder.AppendLine("    private RuntimeCustomConverterCache? _runtimeConverters;");
        builder.AppendLine("    private RuntimeCustomConverterCache RuntimeConverters => _runtimeConverters ??= new RuntimeCustomConverterCache(Options);");
        builder.AppendLine();
        builder.AppendLine("    private static global::Meziantou.Framework.Yaml.YamlSerializerOptions CreateDefaultOptions()");
        builder.AppendLine("    {");
        builder.AppendLine("        return new global::Meziantou.Framework.Yaml.YamlSerializerOptions");
        builder.AppendLine("        {");
        AppendOptionAssignments(builder, model.SourceGenerationOptions);
        builder.AppendLine("        };");
        builder.AppendLine("    }");
        builder.AppendLine();

        var typeInfoPropertyNames = CreateTypeInfoPropertyNames(model, types);

        for (var index = 0; index < types.Length; index++)
        {
            var serializableType = types[index].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            builder.Append("    private global::Meziantou.Framework.Yaml.YamlTypeInfo<").Append(serializableType).Append(">? _typeInfo").Append(index).AppendLine(";");
        }

        builder.AppendLine();
        builder.AppendLine("    private static readonly global::System.Collections.Frozen.FrozenDictionary<global::System.Type, int> s_typeIndexByType =");
        builder.Append("        new global::System.Collections.Generic.Dictionary<global::System.Type, int>(").Append(types.Length).AppendLine(")");
        builder.AppendLine("        {");
        for (var index = 0; index < types.Length; index++)
        {
            var serializableType = types[index].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            builder.Append("            [typeof(").Append(serializableType).Append(")] = ").Append(index).AppendLine(",");
        }
        builder.AppendLine("        }.ToFrozenDictionary();");
        builder.AppendLine();
        builder.AppendLine("    public override global::Meziantou.Framework.Yaml.YamlTypeInfo? GetTypeInfo(global::System.Type type, global::Meziantou.Framework.Yaml.YamlSerializerOptions options)");
        builder.AppendLine("    {");
        builder.AppendLine("        if (!s_typeIndexByType.TryGetValue(type, out var index))");
        builder.AppendLine("        {");
        builder.AppendLine("            return null;");
        builder.AppendLine("        }");
        builder.AppendLine();
        builder.AppendLine("        if (!global::System.Object.ReferenceEquals(options, Options))");
        builder.AppendLine("        {");
        builder.AppendLine("            if (!global::System.Object.ReferenceEquals(options.TypeInfoResolver, this))");
        builder.AppendLine("            {");
        builder.AppendLine("                throw new global::System.InvalidOperationException(");
        builder.AppendLine("                    $\"The provided {nameof(global::Meziantou.Framework.Yaml.YamlSerializerOptions)} instance does not match the options associated with the context '{GetType()}'. \" +");
        builder.AppendLine("                    $\"Use the overloads that accept a {nameof(global::Meziantou.Framework.Yaml.Serialization.YamlSerializerContext)} or a {nameof(global::Meziantou.Framework.Yaml.YamlTypeInfo)} directly.\");");
        builder.AppendLine("            }");
        builder.AppendLine();
        builder.AppendLine("            var runtimeConverters = new RuntimeCustomConverterCache(options);");
        builder.AppendLine("            return index switch");
        builder.AppendLine("            {");
        for (var index = 0; index < types.Length; index++)
        {
            builder.Append("                ").Append(index).Append(" => new GeneratedTypeInfo").Append(index).AppendLine("(options, runtimeConverters),");
        }
        builder.AppendLine("                _ => null,");
        builder.AppendLine("            };");
        builder.AppendLine("        }");
        builder.AppendLine();
        builder.AppendLine("        return index switch");
        builder.AppendLine("        {");
        for (var index = 0; index < types.Length; index++)
        {
            builder.Append("            ").Append(index).Append(" => _typeInfo").Append(index).Append(" ??= new GeneratedTypeInfo").Append(index).AppendLine("(Options, RuntimeConverters),");
        }
        builder.AppendLine("            _ => null,");
        builder.AppendLine("        };");
        builder.AppendLine("    }");
        builder.AppendLine();

        for (var index = 0; index < types.Length; index++)
        {
            var serializableType = types[index].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            var propertyName = typeInfoPropertyNames[index];
            builder.Append("    public global::Meziantou.Framework.Yaml.YamlTypeInfo<").Append(serializableType).Append("> ").Append(propertyName).AppendLine();
            builder.AppendLine("    {");
            builder.Append("        get => _typeInfo").Append(index).Append(" ??= new GeneratedTypeInfo").Append(index).AppendLine("(Options, RuntimeConverters);");
            builder.AppendLine("    }");
            builder.AppendLine();

            AppendGeneratedTypeAttributes(builder, "    ");
            builder.Append("    private sealed class GeneratedTypeInfo").Append(index).Append(" : global::Meziantou.Framework.Yaml.YamlTypeInfo<").Append(serializableType).AppendLine(">");
            builder.AppendLine("    {");
            builder.AppendLine("        private readonly RuntimeCustomConverterCache _runtimeConverters;");
            builder.AppendLine();
            builder.AppendLine("        public GeneratedTypeInfo" + index + "(global::Meziantou.Framework.Yaml.YamlSerializerOptions options, RuntimeCustomConverterCache runtimeConverters) : base(options)");
            builder.AppendLine("        {");
            builder.AppendLine("            _runtimeConverters = runtimeConverters;");
            builder.AppendLine("        }");
            builder.AppendLine();
            builder.Append("        public override void Write(global::Meziantou.Framework.Yaml.Serialization.YamlWriter writer, ").Append(serializableType).AppendLine(" value)");
            builder.AppendLine("        {");
            builder.AppendLine("            global::System.ArgumentNullException.ThrowIfNull(writer);");
            builder.Append("            WriteValue").Append(index).AppendLine("(writer, value, _runtimeConverters);");
            builder.AppendLine("        }");
            builder.AppendLine();
            builder.Append("        public override ").Append(serializableType).Append(types[index].IsReferenceType ? "?" : string.Empty).AppendLine(" Read(global::Meziantou.Framework.Yaml.Serialization.YamlReader reader)");
            builder.AppendLine("        {");
            builder.Append("            return ReadValue").Append(index).AppendLine("(reader, _runtimeConverters);");
            builder.AppendLine("        }");
            builder.AppendLine("    }");
            builder.AppendLine();
        }

        builder.AppendLine();
        for (var index = 0; index < types.Length; index++)
        {
            var typeName = types[index].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            EmitWriteValue(builder, index, types[index], typeName, derivedTypeMappings, indexByType, propertyNamingPolicy, model.SourceGenerationOptions, accessors);
            builder.AppendLine();
            EmitReadValue(builder, index, types[index], typeName, derivedTypeMappings, indexByType, propertyNamingPolicy, model.SourceGenerationOptions, accessors, pendingMembers);
            builder.AppendLine();
        }

        builder.Append(pendingMembers);
        accessors.Emit(builder);
        builder.AppendLine("}");
        return builder.ToString();
    }

