        builder.AppendLine("        }");
        builder.AppendLine("        else if (__ignoreCondition == global::Meziantou.Framework.Yaml.YamlIgnoreCondition.WhenWritingDefault)");
        builder.AppendLine("        {");
        EmitWriteMemberWithDefaultCheck(builder, member, indexByType, memberValueVar, nameVar, "            ", sourceGenerationOptions);
        builder.AppendLine("        }");
        builder.AppendLine("        else");
        builder.AppendLine("        {");
        EmitWriteMemberProperty(builder, member, indexByType, memberValueVar, nameVar, "            ", sourceGenerationOptions);
        builder.AppendLine("        }");
        builder.AppendLine("        }");
    }

    private static void EmitWriteMemberWithKnownIgnoreConditionInt(StringBuilder builder, MemberModel member, Dictionary<ITypeSymbol, int> indexByType, string memberValueVar, string nameVar, int ignoreCondition, SourceGenerationOptionsModel sourceGenerationOptions)
    {
        // ignoreCondition: 0=Never, 1=WhenWritingNull, 2=WhenWritingDefault, 3=Always, 4=WhenWriting, 5=WhenReading
        if (ignoreCondition is 3 /* Always */ or 4 /* WhenWriting */)
        {
            // Always skipped on write — emit nothing
            return;
        }

        builder.Append("        if (").Append(GetShouldSerializeMemberExpression(member)).AppendLine(")");
        builder.AppendLine("        {");
        builder.Append("        var ").Append(memberValueVar).Append(" = ").Append(member.AccessExpression("value")).AppendLine(";");
        var typeName = member.Symbol.ContainingType?.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) ?? "unknown";
        EmitThrowIfNullForNonNullableMemberOnWrite(builder, member, typeName, memberValueVar, "        ");

        if (ignoreCondition is 1 /* WhenWritingNull */)
        {
            EmitWriteMemberWithNullCheck(builder, member, indexByType, memberValueVar, nameVar, "        ", sourceGenerationOptions);
        }
        else if (ignoreCondition is 2 /* WhenWritingDefault */)
        {
            EmitWriteMemberWithDefaultCheck(builder, member, indexByType, memberValueVar, nameVar, "        ", sourceGenerationOptions);
        }
        else
        {
