        builder.AppendLine("        }");
    }

    private static void EmitWriteMemberWithNullCheck(StringBuilder builder, MemberModel member, Dictionary<ITypeSymbol, int> indexByType, string memberValueVar, string nameVar, string indent, SourceGenerationOptionsModel sourceGenerationOptions)
    {
        if (member.Type.IsReferenceType)
        {
            builder.Append(indent).Append("if (").Append(memberValueVar).AppendLine(" is null)");
            builder.Append(indent).AppendLine("{");
            builder.Append(indent).AppendLine("    // Skip null value.");
            builder.Append(indent).AppendLine("}");
            builder.Append(indent).AppendLine("else");
            builder.Append(indent).AppendLine("{");
            EmitWriteMemberProperty(builder, member, indexByType, memberValueVar, nameVar, indent + "    ", sourceGenerationOptions);
            builder.Append(indent).AppendLine("}");
        }
        else
        {
            builder.Append(indent).AppendLine("// Value types are never null.");
            EmitWriteMemberProperty(builder, member, indexByType, memberValueVar, nameVar, indent, sourceGenerationOptions);
        }
    }

    private static void EmitWriteMemberWithDefaultCheck(StringBuilder builder, MemberModel member, Dictionary<ITypeSymbol, int> indexByType, string memberValueVar, string nameVar, string indent, SourceGenerationOptionsModel sourceGenerationOptions)
