        builder.Append(indent).AppendLine("{");
        builder.Append(indent).Append("    throw global::Meziantou.Framework.Yaml.Serialization.YamlThrowHelper.ThrowNullForNonNullableMember(reader, typeof(")
            .Append(declaringTypeName)
