        {
            builder.Append(bodyIndent).Append("WriteValue").Append(typeIndex).Append("(writer, ").Append(valueExpression).AppendLine(", runtimeConverters);");
            builder.Append(innerIndent).AppendLine("}");
            builder.Append(indent).AppendLine("}");
