    private static void EmitWriteWithUntypedObjectConverter(StringBuilder builder, string valueExpression, string indent)
    {
        builder.Append(indent).AppendLine("var objectConverter = writer.GetConverter(typeof(global::System.Object));");
        builder.Append(indent).Append("objectConverter.Write(writer, ").Append(valueExpression).AppendLine(");");
    }

    private static void EmitReadWithYamlNodeConverter(StringBuilder builder, string typeName, string indent, Action<string> emitAssignment)
    {
        builder.Append(indent).Append("var yamlNodeConverter = reader.GetConverter(typeof(").Append(typeName).AppendLine("));");
        builder.Append(indent).Append("var yamlNodeValue = yamlNodeConverter.Read(reader, typeof(").Append(typeName).AppendLine("));");
        builder.Append(indent).AppendLine("if (yamlNodeValue is null)");
        builder.Append(indent).AppendLine("{");
        emitAssignment("default");
        builder.Append(indent).AppendLine("}");
        builder.Append(indent).AppendLine("else");
        builder.Append(indent).AppendLine("{");
        emitAssignment("(" + typeName + ")yamlNodeValue");
        builder.Append(indent).AppendLine("}");
    }

    private static void EmitReadWithUntypedObjectConverter(StringBuilder builder, string indent, Action<string> emitAssignment)
    {
        builder.Append(indent).AppendLine("var objectConverter = reader.GetConverter(typeof(global::System.Object));");
        builder.Append(indent).AppendLine("var objectValue = objectConverter.Read(reader, typeof(global::System.Object));");
        emitAssignment("objectValue");
    }

    private static void EmitWriteWithRuntimeCustomConverter(
        StringBuilder builder,
        string typeName,
        string valueExpression,
        string indent,
        bool emitReturn,
        string variableSuffix)
    {
        var runtimeConverterName = "runtimeConverter" + variableSuffix;
        builder.Append(indent).AppendLine("{");
        builder.Append(indent).Append("if (runtimeConverters.TryGetConverter(typeof(").Append(typeName).Append("), out var ").Append(runtimeConverterName).AppendLine("))");
        builder.Append(indent).AppendLine("{");
        builder.Append(indent).Append("    ").Append(runtimeConverterName).Append("!.Write(writer, ").Append(valueExpression).AppendLine(");");
        if (emitReturn)
        {
            builder.Append(indent).AppendLine("    return;");
        }

        builder.Append(indent).AppendLine("}");
        builder.Append(indent).AppendLine("}");
    }

    private static void EmitReadWithRuntimeCustomConverter(
        StringBuilder builder,
        string typeName,
        string indent,
        string variableSuffix,
        Action<string> emitAssignment)
    {
        var runtimeConverterName = "runtimeConverter" + variableSuffix;
        var runtimeValueName = "runtimeValue" + variableSuffix;
        builder.Append(indent).AppendLine("{");
        builder.Append(indent).Append("if (runtimeConverters.TryGetConverter(typeof(").Append(typeName).Append("), out var ").Append(runtimeConverterName).AppendLine("))");
        builder.Append(indent).AppendLine("{");
        builder.Append(indent).Append("    var ").Append(runtimeValueName).Append(" = ").Append(runtimeConverterName).Append("!.Read(reader, typeof(").Append(typeName).AppendLine("));");
        emitAssignment(runtimeValueName + " is null ? default : (" + typeName + ")" + runtimeValueName);
        builder.Append(indent).AppendLine("}");
        builder.Append(indent).AppendLine("}");
    }

