        builder.AppendLine("        private static bool TryResolve(global::Meziantou.Framework.Yaml.YamlSerializerOptions options, global::System.Type typeToConvert, [global::System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out global::Meziantou.Framework.Yaml.Serialization.YamlConverter? converter)");
        builder.AppendLine("        {");
