            builder.AppendLine(i == sourceGenerationOptions.ConverterTypes.Length - 1 ? ";" : " ||");
        }
    }

    private static bool TryGetStaticOptionsConverterType(SourceGenerationOptionsModel sourceGenerationOptions, ITypeSymbol typeSymbol, out int converterIndex)
    {
        if (sourceGenerationOptions.ConverterTypes.IsDefaultOrEmpty)
        {
            converterIndex = -1;
            return false;
        }

        // Unwrap Nullable<T> for matching.
        var unwrappedType = typeSymbol;
        if (typeSymbol is INamedTypeSymbol nullableType && nullableType.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T)
        {
            unwrappedType = nullableType.TypeArguments[0];
        }

        for (var i = 0; i < sourceGenerationOptions.ConverterTypes.Length; i++)
        {
            // Walk up the base type chain looking for YamlConverter<T> where T matches.
            for (var current = sourceGenerationOptions.ConverterTypes[i] as INamedTypeSymbol; current is not null; current = current.BaseType)
            {
                if (current.IsGenericType &&
                    current.Name == "YamlConverter" &&
                    current.TypeArguments.Length == 1 &&
                    SymbolEqualityComparer.Default.Equals(current.TypeArguments[0], unwrappedType))
                {
                    converterIndex = i;
                    return true;
                }
            }
        }

        converterIndex = -1;
        return false;
    }

}
